_year": 926, "time_original": "926年三月钱镠患病期间", "dynasty": "五代十国", "description": "徐温遣使问疾，钱镠认为意在窥察，仍强起接见。", "phases": [], "location_name": "衣锦军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "67e750f4-b9d4-55bf-8a8f-39b4c8169c99"}, {"title": "徐温聚兵拟袭吴越，闻钱镠病愈而停止，钱镠随后返钱塘", "start_year": 926, "end_year": 926, "time_original": "926年三月钱镠病愈后叙次，确日未载", "dynasty": "五代十国", "description": "徐温聚兵拟袭吴越，闻钱镠病愈而停止，钱镠随后返钱塘。", "phases": [], "location_name": "吴、吴越与钱塘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e6f44056-a132-5dcd-9fe1-350c499a6702"}, {"title": "吴进徐知诰之位，严可求兼门下侍郎、同平章事", "start_year": 926, "end_year": 926, "time_original": "926年三月主书本段叙次，确日未载", "dynasty": "五代十国", "description": "吴进徐知诰之位，严可求兼门下侍郎、同平章事。", "phases": [], "location_name": "吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "df666144-4527-5459-b97e-080fb1c4b054"}, {"title": "李存勖从汜水继续东行", "start_year": 926, "end_year": 926, "time_original": "926年三月庚辰据主书", "dynasty": "五代十国", "description": "李存勖从汜水继续东行。", "phases": [], "location_name": "汜水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "821f506a-fcbc-5c55-af67-85872bbe0f73"}, {"title": "李嗣源在白皋取得山东上供绢船，用绢赏军", "start_year": 926, "end_year": 926, "time_original": "926年三月，主书记“辛已”，已疑巳待核", "dynasty": "五代十国", "description": "李嗣源在白皋取得山东上供绢船，用绢赏军。", "phases": [], "location_name": "白皋", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "659c0fb1-237c-5a23-ab61-78c4d7dea0f4"}, {"title": "白皋