SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李存勖从洛阳东行，至汜水后遣元行钦率骑兵沿河东进。", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p041·原文件第78行", "note": "原文：乙亥，帝发洛阳；丁丑，次汜水；戊寅，遣李绍荣将骑兵循河而东。；核对说明：主所列三日分阶段保留，不合并为同日；旧本纪乙丑出京、戊辰遣骑不同，独立补证。", "status": "draft", "id": "ea6db70e-9778-5317-b7d7-6d7a9cacccf9", "subject_id": "b6cfa198-41bd-51b0-aa52-3b8745e7d62c", "source_id": "d353a3bc-ec27-5ac7-98d9-894953ef7d3d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年三月乙亥发洛阳、丁丑至汜水、戊寅遣骑，据主书", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p041·原文件第78行", "note": "原文：乙亥，帝发洛阳；丁丑，次汜水；戊寅，遣李绍荣将骑兵循河而东。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "7cb264ac-d73f-54ed-b989-11c5526abb46", "subject_id": "b6cfa198-41bd-51b0-aa52-3b8745e7d62c", "source_id": "d353a3bc-ec27-5ac7-98d9-894953ef7d3d"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李存勖：东征者。", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p041·原文件第78行", "note": "原文：乙亥，帝发洛阳；丁丑，次汜水；戊寅，遣李绍荣将骑兵循河而东。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "62de6907-930b-5868-ac8e-ff0f7bde3660", "subject_id": "4e068da9-c8dd-5a31-a747-87669e3bf993", "source_id": "d353a3bc-ec27-5ac7-98d9-894953ef7d3d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李存勖：东征者。", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p041·原文件第78行", "note": "原文：乙亥，帝发洛阳；丁丑，次汜水；戊寅，遣李绍荣将骑兵循河而东。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "42726c00-9fe6-5a11-b03f-5ddddb0c8d88", "subject_id": "a90b58d2-e774-5538-8c09-8650eb2a2429", "source_id": "d353a3bc-ec27-5ac7-98d9-894953ef7d3d"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记元行钦：奉遣率骑者。", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p041·原文件第78行", "note": "原文：乙亥，帝发洛阳；丁丑，次汜水；戊寅，遣李绍荣将骑兵循河而东。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。